	return page(m.segments, opts...), nil
}
func (m *memoryStore) ListRules(_ context.Context, _ string, _ ...storage.QueryOption) ([]*flipt.Rule, error) {
	return m.rules, nil
}
func page[T any](items []T, opts ...storage.QueryOption) []T {
	var p storage.QueryParams
	for _, opt := range opts { opt(&p) }
	if p.Offset >= uint64(len(items)) { return nil }
	end := p.Offset + p.Limit
	if end > uint64(len(items)) { end = uint64(len(items)) }
	return items[p.Offset:end]
}
