	input := "'`flags:
- key: feature
  name: Feature
  enabled: true
  variants:
  - key: first
    attachment:
      items:
      - 1
      - false
      - null
      - nested: [text, 2.5]
      7: [true, {deep: null}]
  - key: empty
  rules:
  - segment: users
    rank: 1
    distributions:
    - variant: first
      rollout: 50
segments:
- key: users
  match_type: ANY_MATCH_TYPE
  constraints:
  - type: STRING_COMPARISON_TYPE
    property: country
    operator: eq
    value: US
`
	ctx := context.Background()
	store := new(memoryStore)
	if err := NewImporter(store).Import(ctx, strings.NewReader(input)); err != nil { t.Fatal(err) }
	if len(store.flags) != 1 || len(store.variants) != 2 || len(store.segments) != 1 || len(store.rules) != 1 || len(store.distributions) != 1 || len(store.segments[0].Constraints) != 1 { t.Fatalf("incomplete import: %+v", store) }
	if store.variants[1].Attachment != "" { t.Fatalf("missing attachment became %q", store.variants[1].Attachment) }
	var attachment interface{}
	if err := json.Unmarshal([]byte(store.variants[0].Attachment), &attachment); err != nil { t.Fatal(err) }
	want := map[string]interface{}{"items": []interface{}{float64(1), false, nil, map[string]interface{}{"nested": []interface{}{"text", 2.5}}}, "7": []interface{}{true, map[string]interface{}{"deep": nil}}}
